from functools import lru_cache

@lru_cache(None)
def dfs(r, c, steps):
    if steps == 1:
        return (grid[r][c],)
    best = None
    for nr, nc in neighbors(r, c):
        path = (grid[r][c],) + dfs(nr, nc, steps-1)
        if best is None or path < best:
            best = path
    return best

